import { control } from './chrome-controls.mjs';
// ADR-0022: the RxInfer library — a coin's bias as a factor graph built in
// the panel. The graph is θ ~ Beta(2, 7), with ten flips y ~ Bernoulli(θ)
// observed as data. The test checks:
// - the bipartite rule refuses a factor–factor wire and a second variable
//   on one channel;
// - inference.jl is generated byte-exact against the golden;
// - when a Julia environment with RxInfer exists (RX_ENV, default the e2e
//   cache's julia-rxinfer project), it runs: seven heads in ten flips
//   give the exact conjugate posterior Beta(9, 10), mean 9/19.
import { chromium } from "playwright";
import fs from "node:fs";
import { spawnSync } from "node:child_process";
const S = process.env.M1_SHOTS ?? ".";
const PORT = process.env.PORT ?? 8080;
const ROOT = process.env.M1_ROOT;
const RX_ENV = process.env.RX_ENV ?? `${process.env.HOME}/.cache/moonkale-e2e/julia-rxinfer`;
const GOLDEN = `# Generated by Moonkale's RxInfer library — a .flow.json's factor graph.
# Run: julia inference.jl (needs RxInfer).
using RxInfer

@model function factor_graph(y)
    θ ~ Beta(2.0, 7.0)
    for i in eachindex(y)
        y[i] ~ Bernoulli(θ)
    end
end

result = infer(
    model = factor_graph(),
    data = (y = [1.0, 1.0, 0.0, 1.0, 1.0, 1.0, 0.0, 1.0, 0.0, 1.0],),
)
println("θ = ", result.posteriors[:θ])
println("mean(θ) = ", mean(result.posteriors[:θ]))
`;
const browser = await chromium.launch({ args: ["--use-angle=swiftshader", "--enable-unsafe-swiftshader", "--ignore-gpu-blocklist"] });
const page = await browser.newPage({ viewport: { width: 1500, height: 900 } });
const logs = [];
page.on("console", (m) => { const t = m.text(); if (!t.includes("session[")) logs.push(`[${m.type()}] ${t.slice(0, 300)}`); });
const step = async (n, f) => { process.stdout.write(`- ${n} … `); await f(); console.log("ok"); };
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const status = () => page.$eval(".mk-flow-status:visible", (e) => ({ blocks: +e.dataset.blocks, wires: +e.dataset.wires, issues: +e.dataset.issues }));
const canvasRect = () => page.$eval(".mk-flow-canvas:visible", (e) => { const r = e.getBoundingClientRect(); return { x: r.left, y: r.top }; });
const positions = async () => JSON.parse(await page.evaluate(() => Object.values(window.moonkale.flowViews)[0].node_positions()));
const screenOf = (id) => page.evaluate((id) => Object.values(window.moonkale.flowViews)[0].node_screen_position(id), id);
const portOf = (id, port) => page.evaluate(({ id, port }) => Object.values(window.moonkale.flowViews)[0].port_screen_position(id, port), { id, port });
const idsOfKind = async (prefix) => Object.keys(await positions()).filter((k) => k.toLowerCase().startsWith(prefix.toLowerCase() + "-"));
// Place a palette block and return the id of the block it created.
const place = async (name) => {
  const before = new Set(Object.keys(await positions().catch(() => ({}))));
  await control(page, 'click', `.mk-flow-palette-block:text-is('${name}')`);
  for (let i = 0; i < 40; i++) {
    const added = Object.keys(await positions()).filter((k) => !before.has(k));
    if (added.length === 1) return added[0];
    await sleep(100);
  }
  throw new Error(`placing ${name} added no block`);
};
const dragPin = async (fromId, fromPort, toId, toPort) => {
  const box = await canvasRect();
  const a = await portOf(fromId, fromPort);
  const b = await portOf(toId, toPort);
  if (!a || !b) throw new Error(`pins not found for ${fromId}.${fromPort} → ${toId}.${toPort}`);
  await page.mouse.move(box.x + a[0], box.y + a[1]);
  await page.mouse.down();
  await page.mouse.move(box.x + b[0], box.y + b[1], { steps: 20 });
  await sleep(120);
  await page.mouse.up();
  await sleep(300);
};
// Select a block, set parameters in the floating editor, deselect. The
// camera may still settle after a placement refit — measure fresh and retry.
const setParams = async (id, values) => {
  let opened = false;
  for (let attempt = 0; attempt < 3 && !opened; attempt++) {
    const box = await canvasRect();
    const p = await screenOf(id);
    await page.mouse.click(box.x + p[0], box.y + p[1]);
    try {
      await page.waitForSelector(".mk-flow-props", { timeout: 3000 });
      opened = true;
    } catch { await sleep(400); }
  }
  if (!opened) throw new Error(`could not select ${id}`);
  for (const [name, value] of Object.entries(values)) {
    const field = page.locator(`.mk-flow-props label.mk-flow-param:has(> span:text-is('${name}')) input`);
    await field.click();
    await field.fill(value);
    await page.keyboard.press("Enter");
    await sleep(250);
  }
  const box = await canvasRect();
  await page.mouse.click(box.x + 6, box.y + 6);
  await sleep(200);
};
const notice = () => page.$eval(".mk-flow .mk-flow-notice", (e) => e.textContent).catch(() => "");
try {
  await step("open folder", async () => {
    await page.goto(`http://127.0.0.1:${PORT}/`, { waitUntil: "networkidle" });
    await page.waitForSelector(".wb-workspace");
    await control(page, 'click', ".mk-explorer-open button[type=submit]");
    await page.waitForFunction(() => document.querySelector(".wb-status-bar").textContent.includes("index:"), null, { timeout: 30000 });
  });
  await step("Extensions panel: enable Flow editor and the RxInfer library", async () => {
    await control(page, 'click', "#mk-rail-extensions");
    await page.waitForSelector(".mk-settings-ext", { timeout: 10000 });
    await control(page, 'click', ".mk-settings-ext:has(.mk-settings-ext-name:text-is('Flow editor')) > label input");
    await control(page, 'click', ".mk-settings-ext:has(.mk-settings-ext-name:text-is('RxInfer library')) > label input");
    await page.waitForFunction(() => /editor-flow/.test(localStorage.getItem("moonkale.settings") || "") && /ext-rxinfer/.test(localStorage.getItem("moonkale.settings") || ""), null, { timeout: 10000 });
  });
  await step("File → New Flow…; the palette offers variables and factors", async () => {
    await control(page, 'click', ".mk-menu-button:has-text('File')");
    await control(page, 'click', ".mk-menu-item:has-text('New Flow')");
    await page.waitForSelector(".mk-flow", { timeout: 15000 });
    await page.waitForSelector(".mk-flow-palette-block", { timeout: 10000 });
    const names = await page.$$eval(".mk-flow-palette-block", (els) => els.map((e) => e.textContent));
    for (const want of ["Variable", "Beta", "Bernoulli", "Normal", "Gamma", "Poisson"])
      if (!names.includes(want)) throw new Error(`${want} missing from the palette: ${names}`);
  });
  let beta, theta, flip, y;
  await step("place the coin: Beta(2, 7) → θ → Bernoulli → y with ten flips", async () => {
    beta = await place("Beta");
    await setParams(beta, { a: "2", b: "7" });
    theta = await place("Variable");
    await setParams(theta, { name: "θ" });
    flip = await place("Bernoulli");
    y = await place("Variable");
    await setParams(y, { name: "y", data: "1, 1, 0, 1, 1, 1, 0, 1, 0, 1" });
    const s = await status();
    if (s.blocks !== 4) throw new Error(`four blocks expected: ${JSON.stringify(s)}`);
  });
  await step("wire it — the variable's one pin fans out, either drag order", async () => {
    await dragPin(beta, "out", theta, "x");
    await dragPin(theta, "x", flip, "p");
    await dragPin(flip, "out", y, "x");
    const s = await status();
    console.log(`\n  status: ${JSON.stringify(s)}`);
    if (s.wires !== 3 || s.issues !== 0) throw new Error("the coin is not wired cleanly");
    await page.screenshot({ path: `${S}/rxinfer-coin.png` });
  });
  await step("the bipartite rule: factor–factor and a second variable on one channel are refused", async () => {
    await dragPin(beta, "a", flip, "p");
    let s = await status();
    let n = await notice();
    console.log(`\n  refused: ${n.slice(0, 70)}`);
    if (s.wires !== 3) throw new Error("the factor–factor wire was accepted");
    if (!/factors connect to variables/.test(n)) throw new Error(`no bipartite notice: "${n}"`);
    await dragPin(y, "x", beta, "out");
    s = await status();
    n = await notice();
    console.log(`  refused: ${n.slice(0, 70)}`);
    if (s.wires !== 3) throw new Error("a second variable on Beta.out was accepted");
    if (!/not a bus/.test(n)) throw new Error(`no channel notice: "${n}"`);
  });
  await step("Generate writes inference.jl — byte-exact against the golden", async () => {
    const btn = await page.$$(".mk-flow-generate");
    if (btn.length !== 1) throw new Error(`expected one generator, found ${btn.length}`);
    const label = await btn[0].textContent();
    if (!/RxInfer/.test(label)) throw new Error(`the button does not name the library: ${label}`);
    await control(page, 'click', ".mk-flow-generate");
    await page.waitForFunction(() => /inference\.jl/.test(document.querySelector(".mk-titlebar-title")?.textContent || ""), null, { timeout: 15000 });
    const generated = fs.readFileSync(`${ROOT}/inference.jl`, "utf8");
    if (generated !== GOLDEN) {
      const a = GOLDEN.split("\n"), b = generated.split("\n");
      for (let i = 0; i < Math.max(a.length, b.length); i++) if (a[i] !== b[i]) console.log(`  ${i}: ${JSON.stringify(a[i])}\n  ${i}: ${JSON.stringify(b[i])}`);
      throw new Error("the generated inference.jl differs from the golden");
    }
  });
  await step("infer: the posterior is Beta(9, 10), mean 9/19 (skipped without an RxInfer env)", async () => {
    if (!fs.existsSync(`${RX_ENV}/Project.toml`)) {
      console.log(`\n  skipped: no RxInfer environment at ${RX_ENV} (julia --project=${RX_ENV} with RxInfer)`);
      return;
    }
    const res = spawnSync("julia", [`--project=${RX_ENV}`, `${ROOT}/inference.jl`], { timeout: 280000, encoding: "utf8" });
    if (res.status !== 0) throw new Error(`julia failed: ${(res.stderr || "").slice(0, 400)}`);
    const m = /mean\(θ\) = ([0-9.eE+-]+)/.exec(res.stdout);
    if (!m) throw new Error(`no posterior mean in the output: ${res.stdout.slice(0, 300)}`);
    const v = parseFloat(m[1]);
    console.log(`\n  ${res.stdout.split("\n").find((l) => l.startsWith("θ = "))}  |  mean(θ) = ${v}`);
    if (Math.abs(v - 9 / 19) > 1e-9) throw new Error(`the posterior mean is not 9/19 (got ${v})`);
  });
  await step("with ModelingToolkit enabled too, the palette still opens on the document's library", async () => {
    await control(page, 'click', "#mk-rail-extensions");
    await page.waitForSelector(".mk-settings-ext", { timeout: 10000 });
    await control(page, 'click', ".mk-settings-ext:has(.mk-settings-ext-name:text-is('ModelingToolkit library')) > label input");
    await control(page, 'click', ".wb-tab:has-text('untitled.flow.json')");
    await page.waitForSelector(".mk-flow-palette select:visible", { timeout: 10000 });
    const title = await page.$eval(".mk-flow-palette-title:visible", (e) => e.textContent);
    const h = await page.$eval(".mk-flow-palette select:visible", (e) => e.getBoundingClientRect().height);
    console.log(`\n  palette: ${title}, picker ${Math.round(h)} px tall`);
    if (title !== "RxInfer") throw new Error(`the palette opened on ${title}`);
    if (h > 40) throw new Error(`the library picker is ${h}px tall`);
  });
  console.log("\nRXINFER E2E: PASS");
} catch (e) {
  console.log("\nFAIL:", e.message);
  await page.screenshot({ path: `${S}/rxinfer-fail.png` }).catch(() => {});
  console.log(logs.slice(-15).join("\n"));
  process.exitCode = 1;
} finally {
  await browser.close();
}
